pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let stream_progress = step_index as f64 / total_items as f64;

    // Adjust score based on bin capacity and post-residual
    if bin_capacity - post_residual > 150 {
        score -= (bin_capacity - post_residual) as f64 * 0.3;
    } else if bin_capacity - post_residual < 40 {
        score += (bin_capacity - post_residual) as f64 * 0.4;
    }

    // Penalize large mean residual
    if mean_residual > bin_residual as f64 + 15 {
        score -= (mean_residual - bin_residual as f64) as f64 * 0.7;
    }

    // Reward fitting bins and next item size compatibility
    if fitting_bins_count > 2 && next_item_size != 0 {
        score += (bin_capacity - post_residual) as f64 * 0.5;
    }

    // Penalize small post-residuals with large next items
    if post_residual < 10 && next_item_size > bin_residual + 5 {
        score -= (next_item_size - bin_residual) as f64 * 0.9;
    }

    // Reward full bins at the end
    if step_index == total_items - 1 && post_residual == 0 {
        score += 95.0;
    } else if post_residual < 25 {
        score += 35.0;
    }

    // Adjust score based on bin utilization and step progress
    score = score * 0.8 + (((step_index as f64 / total_items as f64) . powi (2)) as f64) * 0.2;

    score
}

