pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize creating bins with too much unused space
    if post_residual > 50.0 {
        score += (post_residual - 50.0) * 0.1;
    }

    // Reward bins that can fit the next item without opening new bins
    if fitting_bins_count > 0 && next_item_size <= bin_residual {
        score -= (bin_capacity - bin_residual) as f64 * 0.2;
    } else if fitting_bins_count == 0 && next_item_size <= bin_residual {
        score += (bin_residual - next_item_size) as f64 * 0.1;
    }

    // Penalize using too many bins in the overall stream
    if open_bins_count > total_items / 8 {
        score += (open_bins_count - total_items / 8) as f64 * 0.25;
    }

    // Reward balancing residuals across bins
    if mean_residual < bin_capacity * 0.3 {
        score -= (bin_capacity * 0.3 - mean_residual) as f64 * 0.15;
    } else if mean_residual > bin_capacity * 0.7 {
        score += (mean_residual - bin_capacity * 0.7) as f64 * 0.15;
    }

    // Penalize low post-residuals that may lead to premature bin opening
    if post_residual < 30.0 {
        score += (30.0 - post_residual) as f64 * 0.2;
    }

    // Reward bins with a high utilization ratio
    if bin_capacity - bin_residual > bin_capacity / 2 {
        score -= (bin_capacity - bin_residual - bin_capacity / 2) as f64 * 0.1;
    }

    score
}

